## Code Example
```javascript
// Pseudo sketch: atomic write + outbox
async function applyBalanceChange(userId, delta){
  await db.transaction(async (tx)=>{
    await tx.run('UPDATE balances SET amount = amount + ? WHERE user_id = ?', [delta, userId]);
    await tx.run('INSERT INTO balance_outbox(event_id, user_id, delta) VALUES (?, ?, ?)', [eventId, userId, delta]);
  });
  // Kafka publish happens in a separate transaction tied to the DB commit
}
```

